import { cacheTag } from "next/cache";

export type Product = {
  sku: string;
  name: string;
  price: number;
  stock: number;
  available: boolean;
};

/**
 * Simulates fetching product catalog from ERP/PIM.
 * Cached with "products" tag for fast read-heavy browsing.
 */
async function fetchProductsFromSource(): Promise<Product[]> {
  // Simulate ERP/PIM data source - in production this would be a DB or API call
  return [
    { sku: "SKU-001", name: "Widget Pro", price: 29.99, stock: 150, available: true },
    { sku: "SKU-002", name: "Gadget Plus", price: 49.99, stock: 0, available: false },
    { sku: "SKU-003", name: "Tool Kit Basic", price: 19.99, stock: 320, available: true },
    { sku: "SKU-004", name: "Premium Bundle", price: 99.99, stock: 45, available: true },
    { sku: "SKU-005", name: "Spare Part X", price: 4.99, stock: 1200, available: true },
  ];
}

/**
 * Cached product catalog fetcher. Uses "products" tag for invalidation.
 * Read-heavy workloads benefit from cache; sync action invalidates when upstream changes.
 */
export async function getProducts(): Promise<Product[]> {
  "use cache";
  cacheTag("products");
  return fetchProductsFromSource();
}

