import { revalidateTag } from "next/cache";
import { getProducts } from "@/lib/catalog";

async function syncCatalogAction() {
  "use server";

  // Mark "products" cache stale; next request uses stale-while-revalidate.
  // Admins continue working immediately; catalog refreshes in background.
  revalidateTag("products", "max");

  // Fire-and-forget: in production, queue sync job to ERP/PIM here.
  // Sync can touch thousands of SKUs; we never block the response.
  void triggerBackgroundSync();
}

async function triggerBackgroundSync() {
  // Simulates long-running sync (pricing, inventory, availability from ERP/PIM).
  // In production: call queue API, webhook, or async worker.
  await new Promise((r) => setTimeout(r, 100));
}

export default async function AdminCatalogPage() {
  const products = await getProducts();

  return (
    <div className="min-h-screen bg-zinc-50 p-8">
      <header className="mb-8 flex items-center justify-between border-b border-zinc-200 pb-6">
        <h1 className="text-2xl font-semibold text-zinc-900">
          Product Catalog
        </h1>
        <form action={syncCatalogAction}>
          <button
            type="submit"
            className="rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-zinc-800"
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <p className="mb-6 text-sm text-zinc-500">
        Catalog data is cached for fast browsing. Use &quot;Sync latest
        catalog&quot; when upstream ERP/PIM data changes. Sync runs in the
        background; the list refreshes shortly after across all views.
      </p>

      <div className="overflow-hidden rounded-lg border border-zinc-200 bg-white shadow-sm">
        <table className="min-w-full divide-y divide-zinc-200">
          <thead>
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                SKU
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                Name
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-zinc-500">
                Price
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-zinc-500">
                Stock
              </th>
              <th className="px-6 py-3 text-center text-xs font-medium uppercase tracking-wider text-zinc-500">
                Available
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-200">
            {products.map((product) => (
              <tr key={product.sku} className="hover:bg-zinc-50">
                <td className="whitespace-nowrap px-6 py-4 font-mono text-sm text-zinc-900">
                  {product.sku}
                </td>
                <td className="px-6 py-4 text-sm text-zinc-900">
                  {product.name}
                </td>
                <td className="whitespace-nowrap px-6 py-4 text-right text-sm text-zinc-900">
                  ${product.price.toFixed(2)}
                </td>
                <td className="whitespace-nowrap px-6 py-4 text-right text-sm text-zinc-900">
                  {product.stock}
                </td>
                <td className="px-6 py-4 text-center">
                  <span
                    className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${
                      product.available
                        ? "bg-emerald-100 text-emerald-800"
                        : "bg-zinc-100 text-zinc-600"
                    }`}
                  >
                    {product.available ? "Yes" : "No"}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

